// Product-shaped theme/config residual: empty defaults + fg/current reads,
// startup options presence, and Object.keys over the resulting bag.
function paint(theme = {}) {
  const fg = theme.fg === undefined ? "default" : theme.fg;
  const current = theme.current === undefined ? "none" : theme.current;
  return `${"fg" in theme}:${fg}|${"current" in theme}:${current}`;
}

function startup(options = {}) {
  const retry = options.retryCount === undefined ? 250 : options.retryCount;
  return `${"retryCount" in options}:${retry}`;
}

function describe(cfg = {}) {
  return Object.keys(cfg).sort().join(",") || "-";
}

export const results = [
  paint(),
  paint({}),
  paint({ fg: "red" }),
  paint({ fg: undefined, current: "dark" }),
  paint({ fg: "blue", bg: "black", current: "light" }),
  startup(),
  startup({ retryCount: undefined }),
  startup({ retryCount: 3 }),
  describe(),
  describe({ fg: 1, current: 2 }),
];
